# ---------------------------------------------------------------------------
#  Texto convertido em contornos (PDF sem texto selecionável)
#  Alguns CADs exportam cada letra como desenho. Aqui cada letra (contorno) é
#  comparada com as letras da fonte Arial do próprio Windows.
# ---------------------------------------------------------------------------


# ------------------------------------------------------------------ geometria
def _segmentos(obj, M):
    """Subcaminhos (listas de pontos) de um path, já na coordenada da página."""
    n = pdfium_c.FPDFPath_CountSegments(obj)
    subs, atual, bez = [], [], []
    a, b, c, d, e, f = M
    for k in range(n):
        sg = pdfium_c.FPDFPath_GetPathSegment(obj, k)
        x, y = ctypes.c_float(), ctypes.c_float()
        pdfium_c.FPDFPathSegment_GetPoint(sg, x, y)
        X, Y = a * x.value + c * y.value + e, b * x.value + d * y.value + f
        t = pdfium_c.FPDFPathSegment_GetType(sg)
        if t == pdfium_c.FPDF_SEGMENT_MOVETO:
            if len(atual) > 2:
                subs.append(atual)
            atual, bez = [(X, Y)], []
        elif t == pdfium_c.FPDF_SEGMENT_LINETO:
            atual.append((X, Y))
        elif t == pdfium_c.FPDF_SEGMENT_BEZIERTO:
            bez.append((X, Y))
            if len(bez) == 3:
                p0 = atual[-1] if atual else bez[0]
                (x1, y1), (x2, y2), (x3, y3) = bez
                for s in np.linspace(0.125, 1, 8):
                    u = 1 - s
                    atual.append((u**3 * p0[0] + 3*u*u*s*x1 + 3*u*s*s*x2 + s**3*x3,
                                  u**3 * p0[1] + 3*u*u*s*y1 + 3*u*s*s*y2 + s**3*y3))
                bez = []
    if len(atual) > 2:
        subs.append(atual)
    return subs


def _matriz(obj):
    m = pdfium_c.FS_MATRIX()
    if pdfium_c.FPDFPageObj_GetMatrix(obj, m):
        return (m.a, m.b, m.c, m.d, m.e, m.f)
    return (1, 0, 0, 1, 0, 0)


def _compoe(m1, m2):
    """m1 seguida de m2 (formato PDF a b c d e f)."""
    a1, b1, c1, d1, e1, f1 = m1
    a2, b2, c2, d2, e2, f2 = m2
    return (a1*a2 + b1*c2, a1*b2 + b1*d2, c1*a2 + d1*c2, c1*b2 + d1*d2,
            e1*a2 + f1*c2 + e2, e1*b2 + f1*d2 + f2)


def cor_do_objeto(page, cam, preenchimento=True):
    """Cor (R, G, B) de um objeto pelo caminho de índices [(i,), (i, j)...]."""
    try:
        o = pdfium_c.FPDFPage_GetObject(page.raw, cam[0])
        for k in cam[1:]:
            o = pdfium_c.FPDFFormObj_GetObject(o, k)
        r_, g_, b_, a_ = ctypes.c_uint(), ctypes.c_uint(), ctypes.c_uint(), ctypes.c_uint()
        if preenchimento:
            pdfium_c.FPDFPageObj_GetFillColor(o, r_, g_, b_, a_)
        else:
            pdfium_c.FPDFPageObj_GetStrokeColor(o, r_, g_, b_, a_)
        return (r_.value, g_.value, b_.value)
    except Exception:
        return None


def objetos_preenchidos(page):
    """[(caminho_de_indices, subcaminhos)] dos paths preenchidos (candidatos a texto)."""
    saida = []

    def visita(contar, pegar, M, cam):
        for i in range(contar()):
            o = pegar(i)
            tp = pdfium_c.FPDFPageObj_GetType(o)
            if tp == pdfium_c.FPDF_PAGEOBJ_PATH:
                fm, st = ctypes.c_int(), ctypes.c_int()
                pdfium_c.FPDFPath_GetDrawMode(o, fm, st)
                if fm.value == 0:
                    continue
                subs = _segmentos(o, _compoe(_matriz(o), M))
                if subs:
                    saida.append((cam + (i,), subs))
            elif tp == pdfium_c.FPDF_PAGEOBJ_FORM:
                visita(lambda f=o: pdfium_c.FPDFFormObj_CountObjects(f),
                       lambda k, f=o: pdfium_c.FPDFFormObj_GetObject(f, k),
                       _compoe(_matriz(o), M), cam + (i,))
    visita(lambda: pdfium_c.FPDFPage_CountObjects(page.raw),
           lambda k: pdfium_c.FPDFPage_GetObject(page.raw, k), (1, 0, 0, 1, 0, 0), ())
    return saida


