def _buracos_letra(mask):
    """quantos buracos fechados a letra tem (o, 6, 8, B...)"""
    ys, xs = np.nonzero(mask)
    if not len(ys):
        return 0
    m = np.pad(mask[ys.min():ys.max() + 1, xs.min():xs.max() + 1].astype(np.uint8), 1)
    cs, hi = cv2.findContours(m, cv2.RETR_CCOMP, cv2.CHAIN_APPROX_SIMPLE)
    if hi is None:
        return 0
    lim = 0.02 * m.shape[0] * m.shape[1]
    return sum(1 for i, h in enumerate(hi[0]) if h[3] >= 0 and cv2.contourArea(cs[i]) > lim)


def _vetor(mask):
    """bitmap -> vetor normalizado (proporção mantida, centrado em 32x32)."""
    ys, xs = np.nonzero(mask)
    m = mask[ys.min():ys.max() + 1, xs.min():xs.max() + 1].astype(np.uint8) * 255
    h, w = m.shape
    e = (_N - 4) / max(h, w)
    r = cv2.resize(m, (max(1, round(w * e)), max(1, round(h * e))), interpolation=cv2.INTER_AREA)
    q = np.zeros((_N, _N), np.float32)
    y0, x0 = (_N - r.shape[0]) // 2, (_N - r.shape[1]) // 2
    q[y0:y0 + r.shape[0], x0:x0 + r.shape[1]] = r / 255.0
    q = cv2.GaussianBlur(q, (3, 3), 0).ravel()
    q -= q.mean()
    return q / (np.linalg.norm(q) + 1e-6)


def _vetor_esticado(mask):
    """bitmap -> vetor esticado no quadrado (sem manter a proporção): compara a forma
    de letras de fontes estreitas ou largas (ex.: C de fonte condensada)."""
    ys, xs = np.nonzero(mask)
    m = mask[ys.min():ys.max() + 1, xs.min():xs.max() + 1].astype(np.uint8) * 255
    r = cv2.resize(m, (_N - 4, _N - 4), interpolation=cv2.INTER_AREA)
    q = np.zeros((_N, _N), np.float32)
    q[2:_N - 2, 2:_N - 2] = r / 255.0
    q = cv2.GaussianBlur(q, (3, 3), 0).ravel()
    q -= q.mean()
    return q / (np.linalg.norm(q) + 1e-6)


def _junta_componentes(mask):
    """Componentes conectados agrupados por caractere (i, j, :, Ã, %...)."""
    n, lab, st, _ = cv2.connectedComponentsWithStats(mask.astype(np.uint8), connectivity=8)
    comps = [k for k in range(1, n) if st[k, 4] > 0]
    comps.sort(key=lambda k: st[k, 0])
    grupos = []
    for k in comps:
        x, y, w, h = st[k, :4]
        for g in grupos:
            gx0, gx1, gy0, gy1 = g["x0"], g["x1"], g["y0"], g["y1"]
            sob = min(gx1, x + w) - max(gx0, x)
            sob_v = min(gy1, y + h) - max(gy0, y)
            # junta só peças empilhadas (pingo do i, acento, til...), não letras
            # lado a lado que se encostam por causa do espaçamento (ex.: "RA")
            if sob > 0 and sob >= 0.5 * min(w, gx1 - gx0) and sob_v <= 0.15 * min(h, gy1 - gy0):
                g["ks"].append(k)
                g["x0"], g["x1"] = min(gx0, x), max(gx1, x + w)
                g["y0"], g["y1"] = min(gy0, y), max(gy1, y + h)
                break
        else:
            grupos.append({"ks": [k], "x0": x, "x1": x + w, "y0": y, "y1": y + h})
    saida = []
    for g in grupos:
        m = np.isin(lab, g["ks"])
        ys, xs = np.nonzero(m)
        saida.append((m, (xs.min(), ys.min(), xs.max() + 1, ys.max() + 1)))
    saida.sort(key=lambda t: t[1][0])
    return saida


_MODELOS = None


def _modelos():
    global _MODELOS
    if _MODELOS is not None:
        return _MODELOS
    # sempre as fontes embutidas (mesma leitura em qualquer computador); as do sistema só
    # se as embutidas falharem
    fontes = []
    for _, partes in _FONTES_EMBUTIDAS:
        try:
            fontes.append(io.BytesIO(zlib.decompress(base64.b85decode("".join(partes)))))
        except Exception:
            pass
    if not fontes:
        fontes = [f for f in FONTES if os.path.exists(f)] + \
                 [f for f in FONTES_SERIFA if os.path.exists(f)][:2]
    lst = []
    for f in fontes:
        if hasattr(f, "seek"):
            f.seek(0)
        fonte = ImageFont.truetype(f, 96)
        asc = fonte.getmetrics()[0]
        hb = fonte.getbbox("H")
        cap = hb[3] - hb[1]
        base = 20 + asc
        for ch in CARACTERES:
            im = Image.new("L", (220, 200), 0)
            ImageDraw.Draw(im).text((20, 20), ch, fill=255, font=fonte)
            m = np.array(im) > 127
            if not m.any():
                continue
            ys, xs = np.nonzero(m)
            h, w = ys.max() - ys.min() + 1, xs.max() - xs.min() + 1
            adv = fonte.getlength(ch)
            lsb, rsb = (xs.min() - 20) / cap, (20 + adv - xs.max() - 1) / cap
            lst.append((ch, _vetor(m), h / cap, (base - 1 - ys.max()) / cap,
                        (base - ys.min()) / cap, w / h, lsb, rsb, _vetor_esticado(m), _buracos_letra(m)))
    _MODELOS = (lst, np.stack([t[1] for t in lst]), np.array([t[2:6] for t in lst]),
                np.stack([t[8] for t in lst]), np.array([t[9] for t in lst]))
    return _MODELOS


def _classifica(mask, rh, rb, rt, asp):
    lst, V, F, VE, FU = _modelos()
    v = _vetor(mask)
    d_asp = np.abs(np.log(F[:, 3] / max(asp, 1e-3)))
    # forma com a proporção da letra e esticada (fonte estreita/larga), meio a meio
    prop = V @ v - 0.4 * d_asp
    nota = 0.5 * prop + 0.5 * (VE @ _vetor_esticado(mask) - 0.15 * d_asp)
    pen = (1.2 * np.abs(np.log(F[:, 0] / max(rh, 1e-3))) + 0.8 * np.abs(F[:, 1] - rb) +
           0.8 * np.abs(F[:, 2] - rt))
    nota = nota - pen - 0.15 * np.abs(FU - _buracos_letra(mask))     # buracos diferentes: outra letra
    i = int(np.argmax(nota))
    # a confiança (para saber se é texto) continua a da forma com proporção
    conf = max(float(nota[i]), float(np.max(prop - pen)))
    ch = lst[i][0]
    if ch == "_" and rb < -0.12:          # traço no meio da linha (acima da base) é hífen
        ch = "-"
    return ch, conf, lst[i][6], lst[i][7]


# ------------------------------------------------------------------ leitura
# ang no padrão do pdfium: 0 = normal, 90 = lendo para baixo, 180 = de cabeça
# para baixo, 270 = lendo para cima. (X, Y) = coordenada "em pé" (Y para baixo)
_PARA_PE = {0: lambda x, y: (x, -y), 90: lambda x, y: (-y, -x),
            180: lambda x, y: (-x, y), 270: lambda x, y: (y, x)}
_DE_PE = {0: lambda X, Y: (X, -Y), 90: lambda X, Y: (-Y, -X),
          180: lambda X, Y: (-X, Y), 270: lambda X, Y: (Y, X)}


def _glifos(subs):
    """Agrupa subcaminhos em caracteres: furos vão com o contorno de fora,
    pingos/acentos com a letra de baixo. -> [(subs_do_glifo, (x0, y0, x1, y1))]"""
    caixas = []
    for s in subs:
        a = np.asarray(s)
        caixas.append([a[:, 0].min(), a[:, 1].min(), a[:, 0].max(), a[:, 1].max()])
    ordem = sorted(range(len(subs)), key=lambda i: -(caixas[i][2] - caixas[i][0]) * (caixas[i][3] - caixas[i][1]))
    grupos = []
    for i in ordem:
        x0, y0, x1, y1 = caixas[i]
        tol = 0.02 * max(x1 - x0, y1 - y0)
        for g in grupos:
            X0, Y0, X1, Y1 = g["bb"]
            if x0 >= X0 - tol and y0 >= Y0 - tol and x1 <= X1 + tol and y1 <= Y1 + tol:
                g["i"].append(i)                       # furo (ou parte interna)
                break
        else:
            grupos.append({"i": [i], "bb": [x0, y0, x1, y1]})
    grupos.sort(key=lambda g: g["bb"][0])
    final = []
    for g in grupos:                                  # pingo do i, acentos, ":"...
        x0, y0, x1, y1 = g["bb"]
        for f in final:
            X0, Y0, X1, Y1 = f["bb"]
            sob = min(X1, x1) - max(X0, x0)
            sob_v = min(Y1, y1) - max(Y0, y0)
            if sob > 0 and sob >= 0.5 * min(x1 - x0, X1 - X0) and sob_v <= 0.15 * min(y1 - y0, Y1 - Y0):
                f["i"] += g["i"]
                f["bb"] = [min(X0, x0), min(Y0, y0), max(X1, x1), max(Y1, y1)]
                break
        else:
            final.append({"i": list(g["i"]), "bb": list(g["bb"])})
    return [([subs[i] for i in f["i"]], tuple(f["bb"])) for f in final]


def _raster(subs, bb, esc):
    x0, y0, x1, y1 = bb
    W, H = int((x1 - x0) * esc) + 3, int((y1 - y0) * esc) + 3
    img = np.zeros((H, W), np.uint8)
    pts = [np.round(((np.asarray(s) - (x0, y0)) * esc + 1) * 8).astype(np.int32) for s in subs]
    cv2.fillPoly(img, pts, 1, lineType=cv2.LINE_8, shift=3)
    return img > 0


def _le_glifos(glifos, esc):
    """glifos em pé -> ([(ch, bb, esp)], nota média)"""
    if not glifos:
        return [], -9
    # linhas: as letras altas definem as linhas; vírgula, ponto, hífen entram
    # na linha com que mais se sobrepõem
    hmax = max(g[1][3] - g[1][1] for g in glifos)
    altos = sorted([g for g in glifos if g[1][3] - g[1][1] >= 0.5 * hmax], key=lambda g: g[1][1])
    linhas = []
    for g in altos:
        cy = (g[1][1] + g[1][3]) / 2
        for ln in linhas:
            if ln["y0"] <= cy <= ln["y1"]:
                ln["gs"].append(g)
                break
        else:
            linhas.append({"gs": [g], "y0": g[1][1], "y1": g[1][3]})
    for g in glifos:
        if g[1][3] - g[1][1] >= 0.5 * hmax:
            continue
        melhor = max(linhas, key=lambda ln: min(ln["y1"], g[1][3]) - max(ln["y0"], g[1][1])
                     - 0.01 * abs((ln["y0"] + ln["y1"]) / 2 - (g[1][1] + g[1][3]) / 2))
        if min(melhor["y1"], g[1][3]) - max(melhor["y0"], g[1][1]) > -0.4 * (melhor["y1"] - melhor["y0"]):
            melhor["gs"].append(g)
        else:
            linhas.append({"gs": [g], "y0": g[1][1], "y1": g[1][3]})
    saida, notas = [], []
    for ln in sorted(linhas, key=lambda l: l["y0"]):
        gs = sorted(ln["gs"], key=lambda g: g[1][0])
        alts = np.array([g[1][3] - g[1][1] for g in gs])
        cap = float(np.percentile(alts, 75))
        altos = [g for g in gs if g[1][3] - g[1][1] >= 0.6 * cap]
        base = float(np.median([g[1][3] for g in altos]))
        ant = None
        ini = len(saida)
        for subs, (x0, y0, x1, y1) in gs:
            h, w = y1 - y0, x1 - x0
            m = _raster(subs, (x0, y0, x1, y1), esc)
            if not m.any():
                continue
            ch, nota, lsb, rsb = _classifica(m, h / cap, (y1 - base) / cap, (base - y0) / cap,
                                             w / max(h, 1e-6))
            # espaço: o vão entre as letras descontadas as margens próprias de cada uma
            esp = ant is not None and (x0 - ant[0]) / cap - ant[1] - lsb > 0.2
            saida.append([ch, (x0, y0, x1, y1), esp])
            notas.append(nota)
            ant = (x1, rsb)
        _ajusta_I_l(saida[ini:])
    return saida, float(np.mean(notas)) if notas else -9


def _contexto_numeros(letras):
    """Corrige letra parecida com algarismo quando está grudada num número (mesma palavra):
    l/I -> 1 ("4lm" = 41m), O/o -> 0 ("124OOD" = 12400D, "1OkVA"), S depois de algarismos
    -> 5 ("18Smm" = 185mm). Só troca se o número domina a palavra ou se do outro lado vem
    unidade (m, kV, V, A); em palavra de letras ("FI0S" = FIOS) não troca. Altera no lugar."""
    unidades = set("mMkKVvA")
    alnum = [c for c in letras if c.isalnum()]
    domina = alnum and sum(c.isdigit() for c in alnum) >= 0.5 * len(alnum)

    def letra(c):
        return c.isalpha() and c not in "IlOoS" and c not in unidades
    mudou = True
    while mudou:
        mudou = False
        for k, c in enumerate(letras):
            if c not in "IlOoS":
                continue
            ant = letras[k - 1] if k > 0 else ""
            dep = letras[k + 1] if k + 1 < len(letras) else ""
            if not (ant.isdigit() or dep.isdigit()):
                continue
            outro = dep if ant.isdigit() else ant
            o_apos_numero = c in "Oo" and ant.isdigit()     # "114OOFV", "22OV": O depois de número é 0
            if not domina and letra(outro) and not o_apos_numero:
                continue
            if c in "Il":
                letras[k] = "1"
            elif c in "Oo":
                letras[k] = "0"
            elif c == "S":
                antes = "".join(letras[:k])
                if not (len(antes) >= 2 and antes[-1].isdigit() and antes[-2].isdigit()):
                    continue
                letras[k] = "5"
            mudou = True

def _contexto_texto(txt):
    """_contexto_numeros aplicado a cada palavra de um texto."""
    saida = []
    for palavra in txt.split(" "):
        letras = list(palavra)
        _contexto_numeros(letras)
        saida.append("".join(letras))
    return " ".join(saida)


def _ajusta_I_l(itens):
    palavras, atual = [], []
    for it in itens:
        if it[2] and atual:
            palavras.append(atual); atual = []
        atual.append(it)
    if atual:
        palavras.append(atual)
    for p in palavras:
        letras = [it[0] for it in p if it[0].isalpha() and it[0] not in "Il"]
        maius = sum(c.isupper() for c in letras) >= sum(c.islower() for c in letras)
        for it in p:
            if it[0] in "Il|":
                it[0] = "I" if maius else "l"
        letras = [it[0] for it in p]
        _contexto_numeros(letras)
        for it, c in zip(p, letras):
            it[0] = c


def ler_texto_vetorial(page, nota_min=0.55, alt_max=None, alt_min=1.0):
    """
    Devolve (chars, objetos_de_texto):
      chars: no mesmo formato de ler_caracteres() {"c","l","b","r","t","ang","esp"}
      objetos_de_texto: caminhos de índice dos paths que são texto (para removê-los
      das cópias "só desenho").
    """
    pl, pb, pr, pt = page.get_bbox()
    if alt_max is None:
        alt_max = max(pr - pl, pt - pb) * 0.03
    chars, objs = [], []
    for cam, subs in objetos_preenchidos(page):
        todos = np.array([p for s in subs for p in s])
        w, h = np.ptp(todos[:, 0]), np.ptp(todos[:, 1])
        if min(w, h) <= 0 or min(w, h) > alt_max or len(subs) > 400:
            continue
        angs = (0, 180) if w >= h else (90, 270)
        if len(subs) <= 3 or (len(subs) >= 8 and max(w, h) < 1.6 * min(w, h)):
            angs = (0, 90, 180, 270)                 # texto comprido em bloco quase quadrado: a ~45°
        def legivel(ang_, giro_):
            """desenho técnico: o texto se lê da esquerda para a direita ou de baixo para
            cima (nunca de cabeça para baixo)"""
            c_, s_ = math.cos(math.radians(giro_)), math.sin(math.radians(giro_))
            g_ = _DE_PE[ang_]
            ax, ay = g_(0.0, 0.0)
            bx, by_ = g_(c_, s_)
            dx, dy = bx - ax, by_ - ay
            return dx > 0.17 or (abs(dx) <= 0.17 and dy > 0)
        cands = []
        for ang in angs:
            f = _PARA_PE[ang]
            pe = [[f(x, y) for x, y in s] for s in subs]
            glifos = _glifos(pe)
            hs = sorted(bb[3] - bb[1] for _, bb in glifos)
            esc = 40.0 / max(hs[len(hs) // 2], 1e-3)
            itens, nota = _le_glifos(glifos, esc)
            cands.append((nota, ang, itens, 0.0))
            # texto inclinado (escrito ao longo do cabo): mede a inclinação da linha pelas
            # letras e lê de novo com a palavra endireitada
            if len(subs) >= 3 and len(glifos) >= 3:
                cx = np.array([(bb[0] + bb[2]) / 2 for _, bb in glifos])
                by = np.array([bb[3] for _, bb in glifos])            # pé das letras
                hs_ = np.array([bb[3] - bb[1] for _, bb in glifos])
                altas = hs_ >= 0.6 * hs_.max()
                if altas.sum() >= 2 and np.ptp(cx[altas]) > 0:
                    incl = math.degrees(math.atan(float(np.polyfit(cx[altas], by[altas], 1)[0])))
                    if 4 <= abs(incl) <= 50:
                        c_, s_ = math.cos(math.radians(-incl)), math.sin(math.radians(-incl))
                        pe2 = [[(x * c_ - y * s_, x * s_ + y * c_) for x, y in s] for s in pe]
                        gl2 = _glifos(pe2)
                        hs2 = sorted(bb[3] - bb[1] for _, bb in gl2)
                        it2, nota2 = _le_glifos(gl2, 40.0 / max(hs2[len(hs2) // 2], 1e-3))
                        if nota2 > nota + 0.02:
                            cands.append((nota2, ang, it2, incl))
        def conhecido(itens_):
            txt_ = "".join((" " if e_ else "") + ch_ for ch_, _, e_ in itens_)
            return any(RE_CABO_TEXTO.match(t_) or RE_POSTE_ESF_ALT.match(t_) or
                       re.fullmatch(r"\d{1,4}[mM]", t_) for t_ in txt_.split())
        # a leitura que forma um código conhecido (cabo, poste, metros) leva vantagem: de
        # cabeça para baixo o texto inclinado vira letras soltas ("Ah8,ET-0/#SxE")
        melhor = max(cands, key=lambda c: c[0] + (0.06 if legivel(c[1], c[3]) else 0.0) +
                     (0.12 if conhecido(c[2]) else 0.0))
        nota, ang, itens, giro = melhor
        if nota < nota_min or not itens:
            continue
        if len(itens) == 1 and nota < 0.85:
            continue                                  # um traço solto não é texto
        if max(min(b[3] - b[1], b[2] - b[0]) for _, b, _ in itens) < alt_min:
            continue                                  # pequeno demais para ser letra
        objs.append(cam)
        cor_obj = cor_do_objeto(page, cam, True)
        g = _DE_PE[ang]
        if giro:                         # volta as caixas das letras para a posição original
            c_, s_ = math.cos(math.radians(giro)), math.sin(math.radians(giro))
            g0 = g
            g = lambda X, Y, g0=g0, c_=c_, s_=s_: g0(X * c_ - Y * s_, X * s_ + Y * c_)
        pal, x_ant = 0, None
        for ch, (X0, Y0, X1, Y1), esp in itens:
            if esp or (x_ant is not None and X0 < x_ant):   # palavra nova (espaço ou linha nova)
                pal += 1
            x_ant = X0
            (xa, ya), (xb, yb) = g(X0, Y0), g(X1, Y1)
            chars.append({"c": ch, "l": min(xa, xb), "b": min(ya, yb), "r": max(xa, xb),
                          "t": max(ya, yb), "ang": math.radians(ang), "esp": esp,
                          "pal": ("v",) + tuple(cam) + (pal,), "cor": cor_obj})
    return chars, objs


def ler_caixa_raster(page, bb, alt_px=60.0):
    """Lê o texto de uma caixa (retângulo) desenhando o pedaço da folha como imagem e
    comparando letra por letra com os modelos de letra (serve para texto feito de traços
    simples do CAD, ex.: "3#185mm²2-XLPE"). -> (texto, nota média)"""
    W, H = page.get_size()
    x0, y0, x1, y1 = bb
    if x1 - x0 <= 0 or y1 - y0 <= 0:
        return "", -9
    esc = alt_px / (y1 - y0) if (x1 - x0) >= (y1 - y0) else alt_px / (x1 - x0)
    try:
        im = np.array(page.render(scale=esc, crop=(x0 - 1, y0 - 1, W - x1 - 1, H - y1 - 1),
                                  grayscale=True).to_pil())
    except Exception:
        return "", -9
    if (x1 - x0) < (y1 - y0):                       # caixa em pé: texto lendo para cima
        im = cv2.rotate(im, cv2.ROTATE_90_CLOCKWISE)
    m = (im < 160).astype(np.uint8)
    Hh, Ww = m.shape
    # apaga a borda da caixa: linhas e colunas quase cheias de tinta (e a vizinhança)
    lin = [r for r in np.nonzero(m.mean(1) > 0.85)[0] if r < 0.2 * Hh or r > 0.8 * Hh]
    col = [c_ for c_ in np.nonzero(m.mean(0) > 0.85)[0] if c_ < 0.2 * Ww or c_ > 0.8 * Ww]
    for r in lin:
        m[max(0, r - 1):r + 2, :] = 0
    for c_ in col:
        m[:, max(0, c_ - 1):c_ + 2] = 0
    n, lab, st, _ = cv2.connectedComponentsWithStats(m, connectivity=8)
    # tira a borda da caixa (o componente que ocupa quase toda a largura ou altura)
    comps = [k for k in range(1, n) if st[k, 4] > 3 and st[k, 2] < 0.8 * Ww and st[k, 3] < 0.7 * Hh
             and st[k, 0] > 0.03 * Ww and st[k, 0] + st[k, 2] < 0.97 * Ww]     # sem as laterais
    if not comps:
        return "", -9
    comps.sort(key=lambda k: st[k, 0])
    grupos = []
    for k in comps:
        x, y, w, h = st[k, :4]
        if grupos and min(grupos[-1][1], x + w) - max(grupos[-1][0], x) > 0.5 * min(w, grupos[-1][1] - grupos[-1][0]):
            g = grupos[-1]
            grupos[-1] = (min(g[0], x), max(g[1], x + w), min(g[2], y), max(g[3], y + h), g[4] + [k])
        else:
            grupos.append((x, x + w, y, y + h, [k]))
    hs = np.array([g[3] - g[2] for g in grupos], float)
    cap = float(np.percentile(hs, 75))
    if cap < 4:
        return "", -9
    base = float(np.median([g[3] for g in grupos if g[3] - g[2] >= 0.6 * cap]))
    txt, notas, ant = "", [], None
    for gx0, gx1, gy0, gy1, ks in grupos:
        mm = np.isin(lab, ks)[gy0:gy1, gx0:gx1]
        h, w = gy1 - gy0, gx1 - gx0
        ch, nota, _, _ = _classifica(mm, h / cap, (gy1 - base) / cap, (base - gy0) / cap, w / max(h, 1))
        if ch == "_" and base - (gy0 + gy1) / 2 > 0.2 * cap:
            ch = "-"                                  # traço no meio da linha é hífen
        if ant is not None and (gx0 - ant) / cap > 0.6:
            txt += " "
        txt += ch
        notas.append(nota)
        ant = gx1
    return _contexto_texto(txt), float(np.mean(notas))


def _tracos_de_letra(page, caminhos, max_lado=12.0):
    """Traços pequenos (sem preenchimento) que podem ser letras de fonte de traço, sem os
    tracejados e as molduras de caixa. -> [(pontos Nx2, (x0, y0, x1, y1), indice_obj)]"""
    from ceneged.leitura_pdf.rede import tracejados_soltos, tracos_dos_caminhos  # import tardio: camada de cima
    tr, _ = tracos_dos_caminhos(caminhos)
    try:
        _, soltos = tracejados_soltos(page, caminhos)
    except Exception:
        soltos = set()
    # tracejado de verdade é feito de traços retos (2 pontos); um objeto com letras
    # alinhadas (texto de uma linha) também parece tracejado, mas tem curvas e quebras
    subs_de = {i: subs for i, fill, stroke, subs in caminhos}
    fora = set(soltos)
    for i in tr:
        ss = subs_de.get(i) or []
        if ss and np.mean([len(s_) == 2 for s_ in ss]) >= 0.7:
            fora.add(i)
    out = []
    for i, fill, stroke, subs in caminhos:
        if fill or not stroke or i in fora or len(subs) > 5000:
            continue
        if len(subs) > 20:
            # linha comprida feita de pedacinhos (cerca, hachura, contorno): não é texto
            todos = np.array([q for s_ in subs for q in s_], float)
            if np.ptp(todos[:, 0]) > 150 or np.ptp(todos[:, 1]) > 150:
                tam_med = float(np.median([max(np.ptp(np.asarray(s_)[:, 0]), np.ptp(np.asarray(s_)[:, 1]))
                                           for s_ in subs]))
                n_pts = float(np.median([len(s_) for s_ in subs]))
                if n_pts <= 2 or tam_med < 0.5:
                    continue
        for s in subs:
            a = np.asarray(s, float)
            if len(a) < 2:
                continue
            x0, y0 = a.min(0)
            x1, y1 = a.max(0)
            w, h = x1 - x0, y1 - y0
            if max(w, h) > max_lado or max(w, h) < 0.05:
                continue
            if 4 <= len(a) <= 6 and min(w, h) > 0.5 and math.dist(a[0], a[-1]) < 0.1 * max(w, h) and all(
                    abs(a[k + 1][0] - a[k][0]) < 0.05 * w + 0.05 or abs(a[k + 1][1] - a[k][1]) < 0.05 * h + 0.05
                    for k in range(len(a) - 1)):
                continue                                  # moldura de caixa (fechada, lados retos)
            out.append((a, (x0, y0, x1, y1), i))
    return _sem_linhas_emendadas(out)


def _sem_linhas_emendadas(tracos, lim=20.0):
    """Tira traços retos que, emendados ponta com ponta na mesma direção, formam uma linha
    comprida (cerca, estrada ou contorno desenhados em pedacinhos): não são letras."""
    idx = [k for k, t in enumerate(tracos) if len(t[0]) == 2]
    if len(idx) < 3:
        return tracos
    F = np.array([[t[0][0][0], t[0][0][1], t[0][1][0], t[0][1][1]] for t in (tracos[k] for k in idx)], float)
    L = np.hypot(F[:, 2] - F[:, 0], F[:, 3] - F[:, 1])
    U = np.column_stack([F[:, 2] - F[:, 0], F[:, 3] - F[:, 1]]) / np.maximum(L, 1e-9)[:, None]
    n = len(F)
    pai = list(range(n))

    def r(a):
        while pai[a] != a:
            pai[a] = pai[pai[a]]
            a = pai[a]
        return a
    P = np.vstack([F[:, :2], F[:, 2:]])
    dono = np.concatenate([np.arange(n), np.arange(n)])
    grade = {}
    for q, (x, y) in enumerate(P):
        grade.setdefault((int(x // 0.5), int(y // 0.5)), []).append(q)
    for q, (x, y) in enumerate(P):
        gx, gy = int(x // 0.5), int(y // 0.5)
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                for q2 in grade.get((gx + dx, gy + dy), ()):
                    a, b = dono[q], dono[q2]
                    if a != b and abs(U[a] @ U[b]) >= 0.98 and math.hypot(P[q2, 0] - x, P[q2, 1] - y) <= 0.3:
                        pai[r(a)] = r(b)
    soma = {}
    for k in range(n):
        soma[r(k)] = soma.get(r(k), 0.0) + L[k]
    tirar = {idx[k] for k in range(n) if soma[r(k)] > lim}
    return [t for k, t in enumerate(tracos) if k not in tirar]


def _grupos_de_tracos(tracos, cores=None):
    """Junta traços próximos (letras de uma palavra e linhas de um mesmo bloco).
    cores: cor de cada traço; traços de cores diferentes não se juntam (o pontilhado
    amarelo da cerca passando rente ao "40m" preto)."""
    n = len(tracos)
    if not n:
        return []
    B = np.array([t[1] for t in tracos], float)
    tam = np.maximum(B[:, 2] - B[:, 0], B[:, 3] - B[:, 1])
    pai = list(range(n))

    def r(i):
        while pai[i] != i:
            pai[i] = pai[pai[i]]
            i = pai[i]
        return i
    ordem = np.argsort(B[:, 0])
    tmax = float(tam.max())
    for a_ in range(n):
        i = ordem[a_]
        for b_ in range(a_ + 1, n):
            j = ordem[b_]
            if B[j, 0] - B[i, 2] > 0.6 * tmax:
                break
            lim = 0.65 * max(tam[i], tam[j]) + 0.2
            mesma_cor_ = (cores is not None and cores[i] is not None and cores[j] is not None and
                          max(abs(x_ - y_) for x_, y_ in zip(cores[i], cores[j])) <= 60)
            if not mesma_cor_ and max(tam[i], tam[j]) > 4 * max(min(tam[i], tam[j]), 0.05) and \
                    min(tam[i], tam[j]) < 0.6:
                continue                       # pontinho de linha decorativa não liga em letra
            gx = max(B[j, 0] - B[i, 2], B[i, 0] - B[j, 2], 0)
            gy = max(B[j, 1] - B[i, 3], B[i, 1] - B[j, 3], 0)
            if math.hypot(gx, gy) <= lim:
                if cores is not None and cores[i] is not None and cores[j] is not None and \
                        max(abs(x_ - y_) for x_, y_ in zip(cores[i], cores[j])) > 60:
                    continue
                pai[r(i)] = r(j)
    grupos = {}
    for k in range(n):
        grupos.setdefault(r(k), []).append(k)
    # letra que ficou sozinha (o "7" do "70m" em fonte com espaço largo): entra no grupo
    # mais perto, se estiver a até ~1 letra de distância
    gl = list(grupos.values())
    caixas = [(B[g, 0].min(), B[g, 1].min(), B[g, 2].max(), B[g, 3].max()) for g in gl]
    sozinhos = [i for i, g in enumerate(gl) if len(g) <= 2]
    for i in sozinhos:
        x0, y0, x1, y1 = caixas[i]
        t_ = max(x1 - x0, y1 - y0)
        melhor = None
        for j, (a0, b0, a1, b1) in enumerate(caixas):
            if j == i or len(gl[j]) < 2 or (len(gl[j]) <= 2 and j in sozinhos):
                continue
            d = math.hypot(max(a0 - x1, x0 - a1, 0), max(b0 - y1, y0 - b1, 0))
            if d <= 1.0 * t_ + 0.2 and (melhor is None or d < melhor[0]):
                melhor = (d, j)
        if melhor:
            gl[melhor[1]] = gl[melhor[1]] + gl[i]
            gl[i] = []
    saida = []
    for g in gl:
        if not g:
            continue
        ext = max(B[g, 2].max() - B[g, 0].min(), B[g, 3].max() - B[g, 1].min())
        if ext > 60 * max(float(np.median(tam[g])), 0.3):
            continue                           # comprido demais para ser texto (linha desenhada)
        saida.append(g)
    return saida


def _le_linha_raster(m, cap_min=6):
    """Lê uma linha de texto (tinta=1), letra por letra com os modelos.
    -> [(ch, (x0, y0, x1, y1) em pixels, espaço_antes, nota)]"""
    n, lab, st, _ = cv2.connectedComponentsWithStats(m, connectivity=8)
    comps = sorted([k for k in range(1, n) if st[k, 4] > 2], key=lambda k: st[k, 0])
    grupos = []
    for k in comps:
        x, y, w, h = st[k, :4]
        if grupos and min(grupos[-1][1], x + w) - max(grupos[-1][0], x) > 0.5 * min(w, grupos[-1][1] - grupos[-1][0]):
            g = grupos[-1]
            grupos[-1] = (min(g[0], x), max(g[1], x + w), min(g[2], y), max(g[3], y + h), g[4] + [k])
        else:
            grupos.append((x, x + w, y, y + h, [k]))
    if not grupos:
        return []
    hs = np.array([g[3] - g[2] for g in grupos], float)
    cap = float(np.percentile(hs, 75))
    if cap < cap_min:
        return []
    altos = [g for g in grupos if g[3] - g[2] >= 0.6 * cap]
    base = float(np.median([g[3] for g in altos])) if altos else float(max(g[3] for g in grupos))
    out, ant = [], None
    for gx0, gx1, gy0, gy1, ks in grupos:
        h, w = gy1 - gy0, gx1 - gx0
        if max(h, w) > 2.5 * cap:
            ant = None
            continue                                  # traço comprido: não é letra
        mm = np.isin(lab, ks)[gy0:gy1, gx0:gx1]
        ch, nota, _, _ = _classifica(mm, h / cap, (gy1 - base) / cap, (base - gy0) / cap, w / max(h, 1))
        if ch == "_" and base - (gy0 + gy1) / 2 > 0.2 * cap:
            ch = "-"
        esp = ant is not None and (gx0 - ant) / cap > 0.55
        out.append([ch, (gx0, gy0, gx1, gy1), esp, nota])
        ant = gx1
    return out


_DEPURA_TRACO = None


def _texto_conhecido(itens):
    """os itens lidos (letra, caixa, espaço antes, linha, nota) formam algum código conhecido:
    cabo ("3xS4/0-13,8kV"), poste ("400/12") ou metros ("40m")?"""
    txt = ""
    linha_ant = None
    for it in itens:
        if txt and (it[2] or it[3] != linha_ant):
            txt += " "
        txt += it[0]
        linha_ant = it[3]
    for t in txt.split():
        if RE_CABO_TEXTO.match(t) or RE_POSTE_ESF_ALT.match(t) or re.fullmatch(r"\d{1,4}[mM]", t):
            return True
    return False


def ler_texto_de_traco(page, caminhos, nota_min=0.5):
    """Texto escrito com fonte de traço (letras feitas de linhas, sem preenchimento), em
    qualquer fonte e em qualquer inclinação: junta os traços em blocos, mede a direção do
    texto, desenha o bloco endireitado com espessura de fonte normal e lê letra por letra
    com os modelos de fonte. -> chars no formato de ler_caracteres()"""
    tracos = _tracos_de_letra(page, caminhos)
    chars = []
    cor_obj = {}
    for t_ in tracos:
        if t_[2] not in cor_obj:
            try:
                cor_obj[t_[2]] = cor_do_objeto(page, (t_[2],), False)
            except Exception:
                cor_obj[t_[2]] = None
    for g in _grupos_de_tracos(tracos, [cor_obj[t_[2]] for t_ in tracos]):
        pts_all = np.vstack([tracos[k][0] for k in g])
        ext = pts_all.max(0) - pts_all.min(0)
        if len(g) < 2 or max(ext) < 0.8:
            continue
        c0 = pts_all.mean(0)
        u = pts_all - c0
        _, sv, vt = np.linalg.svd(u, full_matrices=False)
        th_pca = math.degrees(math.atan2(vt[0][1], vt[0][0]))
        angs = {round(th_pca, 1) % 360, (round(th_pca, 1) + 180) % 360}
        if sv[0] < 1.8 * sv[1]:                        # bloco curto: tenta também em pé/deitado
            angs |= {0.0, 90.0, 180.0, 270.0}
        leque = set()
        if len(g) <= 14:                               # rótulo curto: a direção pela forma
            for d_ in (-20, -10, 10, 20):              # das letras é imprecisa; tenta em volta
                leque |= {round(th_pca + d_, 1) % 360, round(th_pca + d_ + 180, 1) % 360}
        tam = float(np.median([max(tracos[k][1][2] - tracos[k][1][0], tracos[k][1][3] - tracos[k][1][1]) for k in g]))
        k_esc = 32.0 / max(tam, 1e-3)
        melhor = None

        def ler_em(th, cis=0.0, alvo=32.0, esp_px=None):
            ct, st_ = math.cos(math.radians(-th)), math.sin(math.radians(-th))
            R = np.array([[ct, -st_], [st_, ct]])
            rot = [(tracos[k][0] - c0) @ R.T for k in g]
            if cis:                                    # itálico: desfaz a inclinação das letras
                rot = [np.column_stack([p_[:, 0] - cis * p_[:, 1], p_[:, 1]]) for p_ in rot]
            todos = np.vstack(rot)
            mn = todos.min(0)
            k_ = alvo / max(tam, 1e-3)
            W_ = int((todos[:, 0].max() - mn[0]) * k_) + 12
            H_ = int((todos[:, 1].max() - mn[1]) * k_) + 12
            if W_ * H_ > 4_000_000:
                return None
            img = np.zeros((H_, W_), np.uint8)
            esp_ = esp_px or max(2, int(round(0.11 * 32 * 1.4)))
            for p_ in rot:
                q = np.column_stack([(p_[:, 0] - mn[0]) * k_ + 6, H_ - ((p_[:, 1] - mn[1]) * k_ + 6)])
                cv2.polylines(img, [np.round(q * 8).astype(np.int32)], False, 1, esp_, lineType=cv2.LINE_8, shift=3)
            # tira pedaços muito mais altos que as letras (símbolo ao lado do texto), que
            # atrapalham a separação das linhas
            n_c, lab_c, st_c, _ = cv2.connectedComponentsWithStats(img, connectivity=8)
            if n_c > 3:
                hs_c = st_c[1:, 3]
                h_med = float(np.median(hs_c))
                for k_c in range(1, n_c):
                    if st_c[k_c, 3] > 1.8 * h_med and st_c[k_c, 2] > 0.8 * h_med:
                        img[lab_c == k_c] = 0
            perfil = img.sum(1) > 0
            faixas, ini = [], None
            for y_, v in enumerate(list(perfil) + [False]):
                if v and ini is None:
                    ini = y_
                elif not v and ini is not None:
                    faixas.append((ini, y_))
                    ini = None
            itens, notas = [], []
            hmax = max((b - a for a, b in faixas), default=0)
            for n_f, (a, b) in enumerate(faixas):
                if b - a < 0.35 * hmax and itens:
                    continue
                for it in _le_linha_raster(img[a:b]):
                    x0_, y0_, x1_, y1_ = it[1]
                    itens.append((it[0], (x0_, y0_ + a, x1_, y1_ + a), it[2], n_f, it[3]))
                    notas.append(it[3])
            if not itens:
                return None
            # inclinação que sobrou: pés das letras altas de uma linha só
            resto = 0.0
            if len(faixas) == 1 and len(itens) >= 3:
                cx = np.array([(i_[1][0] + i_[1][2]) / 2 for i_ in itens])
                pe = np.array([i_[1][3] for i_ in itens])
                hs_ = np.array([i_[1][3] - i_[1][1] for i_ in itens])
                alt = hs_ >= 0.6 * hs_.max()
                if alt.sum() >= 2 and np.ptp(cx[alt]) > 0:
                    resto = math.degrees(math.atan(float(np.polyfit(cx[alt], pe[alt], 1)[0])))
            return float(np.mean(notas)), th, itens, mn, H_, resto, cis, k_
        vistos = set()
        fila = list(angs)
        leque_usado = False
        while fila or (not leque_usado and leque and (melhor is None or melhor[0] < 0.72)):
            if not fila:                               # leitura fraca: tenta o leque de ângulos
                fila = sorted(leque)
                leque_usado = True
            th = fila.pop(0)
            if round(th, 1) in vistos:
                continue
            vistos.add(round(th, 1))
            r_ = ler_em(th)
            if r_ is None:
                continue
            # desenho técnico: texto se lê da esquerda para a direita ou de baixo para cima
            # (nunca de cabeça para baixo) - a direção legível leva vantagem no empate
            nota_ = r_[0] + (0.06 if math.cos(math.radians(th)) > -0.1 else 0.0)
            if melhor is None or nota_ > melhor[5]:
                melhor = r_[:5] + (nota_, r_[6], r_[7])
            # endireita pelo pé das letras e lê de novo (uma vez por direção)
            if abs(r_[5]) >= 3 and len(vistos) < 12:
                fila.append((th + r_[5]) % 360)
                fila.append((th + r_[5] + 180) % 360)
        # letra itálica: tenta a palavra endireitada na direção escolhida
        if melhor is not None and melhor[0] < 0.75:
            for cis_, alvo_, esp_px_ in ((0.2, 32.0, None), (0.35, 32.0, None), (0.22, 48.0, 3), (0.3, 48.0, 3)):
                r_ = ler_em(melhor[1], cis_, alvo_, esp_px_)
                if r_ is not None and r_[0] > melhor[0] + 0.03:
                    nota_ = r_[0] + (0.06 if math.cos(math.radians(melhor[1])) > -0.1 else 0.0)
                    melhor = r_[:5] + (nota_, cis_, r_[7])
        if melhor is None or melhor[0] < nota_min:
            continue
        nota, th, itens, mn, H_ = melhor[:5]
        cis = melhor[6]
        k_esc = melhor[7]
        if _DEPURA_TRACO is not None:
            _DEPURA_TRACO.append((th, nota, "".join(i[0] for i in itens), g))
        if len(itens) == 1 and nota < 0.8:
            continue
        # correções de contexto por palavra
        palavras, atual = [], []
        for it in itens:
            if atual and (it[2] or it[3] != atual[-1][3]):   # espaço ou linha nova
                palavras.append(atual)
                atual = []
            atual.append(list(it))
        if atual:
            palavras.append(atual)
        ct, st_ = math.cos(math.radians(th)), math.sin(math.radians(th))
        ang_pdf = (-round(th / 90.0) * 90) % 360            # sentido do pdfium (horário)
        objs_g = [tracos[k][2] for k in g]
        obj_g = max(set(objs_g), key=objs_g.count)
        cor_g = cor_do_objeto(page, (obj_g,), False)
        for n_pal, pal in enumerate(palavras):
            letras = [it[0] for it in pal]
            # "palavra" que é quase só sinal (risquinhos de chamada, hachura): não é texto
            if sum(ch.isalnum() for ch in letras) < 0.5 * len(letras) or \
                    sum(ch.isalnum() for ch in letras) < 2:
                continue                      # sinal solto ou letra sozinha: não é texto
            nota_pal = float(np.mean([it[4] for it in pal]))
            if _DEPURA_TRACO is not None:
                _DEPURA_TRACO.append(("palavra", nota_pal, "".join(letras), g))
            if not any(ch.isdigit() for ch in letras) and nota_pal < 0.72:
                continue                      # só letras e leitura fraca: símbolo, não texto
            _contexto_numeros(letras)
            for it, ch in zip(pal, letras):
                x0_, y0_, x1_, y1_ = it[1]
                cant = []
                for X, Y in ((x0_, y0_), (x1_, y0_), (x0_, y1_), (x1_, y1_)):
                    xr = (X - 6) / k_esc + mn[0]
                    yr = (H_ - Y - 6) / k_esc + mn[1]
                    xr = xr + cis * yr                  # volta o itálico
                    cant.append((c0[0] + xr * ct - yr * st_, c0[1] + xr * st_ + yr * ct))
                cant = np.array(cant)
                chars.append({"c": ch, "l": float(cant[:, 0].min()), "b": float(cant[:, 1].min()),
                              "r": float(cant[:, 0].max()), "t": float(cant[:, 1].max()),
                              "ang": math.radians(ang_pdf), "esp": bool(it[2]), "traco": True,
                              "pal": ("t", g[0], n_pal), "cor": cor_g})
    return chars


def remover_objetos(page, caminhos):
    """Remove objetos pelo caminho de índices [(i,), (i, j)...] (j = dentro de bloco)."""
    for cam in sorted(caminhos, reverse=True):
        if len(cam) == 1:
            o = pdfium_c.FPDFPage_GetObject(page.raw, cam[0])
            if o and pdfium_c.FPDFPage_RemoveObject(page.raw, o):
                pdfium_c.FPDFPageObj_Destroy(o)
        else:
            pai = pdfium_c.FPDFPage_GetObject(page.raw, cam[0])
            for k in cam[1:-1]:
                pai = pdfium_c.FPDFFormObj_GetObject(pai, k)
            o = pdfium_c.FPDFFormObj_GetObject(pai, cam[-1])
            if o and pdfium_c.FPDFFormObj_RemoveObject(pai, o):
                pdfium_c.FPDFPageObj_Destroy(o)
    page.gen_content()
